using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Handy Haversack (2014 ruleset). SRD 5.1 text (CC BY 4.0) in English and in the official Italian SRD 5.1 (CC BY 4.0).
///	</summary>
public static class HandyHaversack2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("handy-haversack", null, 0, MagicItemType.WondrousItem, ItemRarity.Rare, false, ContentSource.Srd51,
			null,
			("Zainetto pratico", "Oggetto meraviglioso, raro",
			"Questo zaino è dotato di una tasca centrale e due laterali, che si aprono su altrettanti spazi extradimensionali. Ognuna delle tasche laterali può custodire fino a 10 kg di materiale, per un volume che non superi 2 cubi con spigolo di 30 cm. La tasca centrale, più grande, può custodire oggetti per un volume massimo pari a 8 cubi con spigolo di 30 cm o del peso di 40 kg. Lo zaino pesa sempre 2,5 kg, a prescindere dal contenuto.\n\nPer inserire un oggetto nello zainetto, si applicano le normali regole relative alle interazioni con gli oggetti. Per recuperare un oggetto dallo zainetto, il personaggio deve usare un'azione. Quando fruga nello zainetto alla ricerca di un oggetto specifico, questo si trova sempre magicamente in cima.\n\nLo zainetto ha alcune limitazioni. Se viene caricato eccessivamente o se un oggetto acuminato lo buca o lo strappa, lo zainetto si rompe ed è distrutto. Se lo zainetto viene distrutto, gli oggetti contenuti al suo interno sono perduti per sempre, anche se un manufatto prima o poi rispunterà fuori da qualche altra parte. Se lo zainetto viene rivoltato, tutto ciò che conteneva cade a terra senza danneggiarsi, ma lo zainetto deve essere rivoltato di nuovo per poter essere riutilizzato. Se nello zainetto viene fatta entrare una creatura che necessita di respirare, quella creatura può sopravvivere per un massimo di 10 minuti, dopodiché inizia a soffocare.\n\nCollocare uno zainetto all'interno di uno spazio extradimensionale, come quello creato da una *borsa conservante,* un *buco portatile* o da altri oggetti simili, distrugge istantaneamente entrambi gli oggetti e apre un portale sul Piano Astrale. Il portale ha origine nel punto in cui uno dei due oggetti è stato inserito nell'altro. Tutte le creature entro 3 metri dal portale vengono attirate al suo interno e depositate in un luogo casuale del Piano Astrale, dopodiché il portale si chiude. Il portale è a senso unico e non può essere riaperto. Alcuni oggetti magici sono dotati di mente e personalità proprie. Gli oggetti di questo tipo potrebbero essere posseduti, infestati dagli spiriti di un precedente proprietario oppure potrebbero essere senzienti grazie alla magia usata nella loro creazione. In ogni caso, un oggetto di questo tipo si comporta come un personaggio, con tanto di peculiarità, ideali, legami e a volte difetti. Un oggetto"),
			("Handy Haversack", "Wondrous item, rare",
			"This backpack has a central pouch and two side pouches, each of which is an extradimensional space. Each side pouch can hold up to 20 pounds of material, not exceeding a volume of 2 cubic feet. The large central pouch can hold up to 8 cubic feet or 80 pounds of material. The backpack always weighs 5 pounds, regardless of its contents.\n\nPlacing an object in the haversack follows the normal rules for interacting with objects. Retrieving an item from the haversack requires you to use an action. When you reach into the haversack for a specific item, the item is always magically on top.\n\nThe haversack has a few limitations. If it is overloaded, or if a sharp object pierces it or tears it, the haversack ruptures and is destroyed. If the haversack is destroyed, its contents are lost forever, although an artifact always turns up again somewhere. If the haversack is turned inside out, its contents spill forth, unharmed, and the haversack must be put right before it can be used again. If a breathing creature is placed within the haversack, the creature can survive for up to 10 minutes, after which time it begins to suffocate.\n\nPlacing the haversack inside an extradimensional space created by a bag of holding, portable hole, or similar item instantly destroys both items and opens a gate to the Astral Plane. The gate originates where the one item was placed inside the other. Any creature within 10 feet of the gate is sucked through it and deposited in a random location on the Astral Plane. The gate then closes. The gate is one-way only and can't be reopened.", "Heward's Handy Haversack"));
	}
}
